  if (!s) {
    return [];
  }

  const res = [];
  let current = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === c) {
      res.push(current.join(""));
      current = [];
    } else {
      current.push(s[i]);
    }
    i++;
  }
  res.push(current.join(""));
  return res;
}

